pipeline {
  agent {
    kubernetes {
      yaml '''
      spec:
        containers:
          - name: maven
            image: maven:3.8.6-openjdk-11
            command: ['cat']
            tty: true
          - name: docker
            image: docker:20.10
            command: ['cat']
            tty: true
      '''
    }
  }
  stages {
    stage('Build') {
      steps {
        container('maven') { sh 'mvn package' }
        container('docker') { sh 'docker build .' }
      }
    }
  }
}

